import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.io.IOException;

public class Main {
    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String[] parts = br.readLine().trim().split("\\s+");
        long s = Long.parseLong(parts[0]);
        long x = Long.parseLong(parts[1]);

        long c = s - x;
        if (c < 0 || (c & 1L) != 0L) {
            System.out.println(0);
            return;
        }

        c >>= 1; // c = (s - x) / 2

        // Check that a & b == c is possible: (c & x) must be 0
        if ((c & x) != 0L) {
            System.out.println(0);
            return;
        }

        // Count number of bits set in x
        int bits = Long.bitCount(x);
        long ans = 1L << bits;

        // Exclude the case where a or b is zero.
        // When c == 0, the pair (0, x) and (x, 0) are counted but invalid (a,b must be positive).
        if (c == 0) {
            ans -= 2;
        }

        System.out.println(ans);
    }
}

