import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.io.IOException;

public class Main {
    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String[] parts = br.readLine().trim().split("\\s+");
        long s = Long.parseLong(parts[0]);
        long x = Long.parseLong(parts[1]);

        long d = s - x;
        if (d < 0 || (d & 1L) != 0L) {
            System.out.println(0);
            return;
        }

        long c = d >> 1; // carry
        // a = c + x, b = c
        if (c == 0 && x == 0) {
            System.out.println(0);
            return;
        }

        // Check that a and b are positive
        if (c <= 0 || c + x <= 0) {
            System.out.println(0);
            return;
        }

        // c & x must be 0 (no overlapping bits)
        if ((c & x) != 0L) {
            System.out.println(0);
            return;
        }

        // Count number of zero bits in x (up to highest bit needed)
        int zeros = 0;
        long tempX = x;
        while (tempX > 0) {
            if ((tempX & 1L) == 0L) zeros++;
            tempX >>= 1;
        }

        // For bits beyond highest bit of x, they must be 0 in both a and b
        // so they don't contribute choices.

        long result = 1L << zeros;

        // If c == 0, then a = x, b = 0, but b must be positive, so subtract invalid pairs.
        // However, we already checked c > 0 above, so no need to adjust.
        System.out.println(result);
    }
}

