        String[] parts = br.readLine().trim().split("\\s+");
        long s = Long.parseLong(parts[0]);
        long x = Long.parseLong(parts[1]);

        long d = s - x;
        if (d < 0 || (d & 1L) != 0) {
            System.out.println(0);
            return;
        }

        long c = d >> 1; // carry
        // a + b = s, a ^ b = x, a & b = c

        // Check that x and c don't share bits: (a&b) and (a^b) must be disjoint
        if ((x & c) != 0) {
            System.out.println(0);
            return;
        }

        // Count number of bits set in x
        int bits = Long.bitCount(x);
        long ans = 1L << bits;

        // Exclude the case where a or b is zero.
        // When c == 0, one of the solutions is (0, x) and (x, 0), which are invalid.
        if (c == 0) {
            ans -= 2;
        }

        System.out.println(ans < 0 ? 0 : ans);
    }
}

