        long d = s - x;
        if (d < 0 || (d & 1L) != 0L) {
            System.out.println(0);
            return;
        }

        long c = d >> 1; // carry
        // a + b = s, a ^ b = x, a & b = c

        // Check that x and c don't share any set bits: they must be disjoint
        if ((x & c) != 0L) {
            System.out.println(0);
            return;
        }

        // Count number of bits set in x
        int bits = Long.bitCount(x);

        // Number of non-negative (a,b) pairs is 2^bits
        long ans = 1L << bits;

        // Exclude the case where both a and b are zero (only possible when s == x)
        if (s == x) {
            ans -= 2; // remove (0,0) counted twice as ordered pair
        }

        System.out.println(ans);
    }
}

