        long c = s - x;
        if (c < 0 || (c & 1L) != 0) {
            System.out.println(0);
            return;
        }

        long carry = c >> 1;
        if ((carry & x) != 0) {
            System.out.println(0);
            return;
        }

        long countZeroBits = 0;
        for (int i = 0; i < 60; i++) {
            long bitX = (x >> i) & 1L;
            long bitC = (carry >> i) & 1L;
            if (bitX == 0 && bitC == 0) {
                countZeroBits++;
            }
        }

        long result = (1L << countZeroBits);
        if (x == s) {
            result -= 2;
        }

        System.out.println(result);
    }
}

